async (page) => {
  const { exec } = require('child_process');
  const fs = require('fs');
  const path = '/tmp/mcp-workspace/backup_md.sh';

  // Make the script executable
  fs.chmodSync(path, '755');

  // Execute the script
  return new Promise((resolve, reject) => {
    exec(`cd /tmp/mcp-workspace && bash ${path}`, (error, stdout, stderr) => {
      if (error) {
        reject(`Error: ${error.message}`);
        return;
      }
      if (stderr) {
        resolve(`Stderr: ${stderr}\nStdout: ${stdout}`);
        return;
      }
      resolve(stdout);
    });
  });
}

